async function list_models(params, userSettings, authorizedResources){

  // --- STEP 1: FETCH DATA (No Auth Required) ---
  const res = await fetch('https://openrouter.ai/api/v1/images/models', {
    headers: {
      'HTTP-Referer': window.location.origin || 'https://typingmind.com',
      'X-Title': 'TypingMind Plugin'
    }
  });

  if (!res.ok) throw new Error(`Failed to fetch models: ${res.statusText}`);
  const data = await res.json();

  // --- STEP 2: FILTER & MAP TO DESIGN SYSTEM CARDS ---
  const models = data.data.filter(m => m.id !== null && m.name);

  return {
    cards: models.map(model => {
      const arch = model.architecture || {};
      const inputMods = arch.input_modalities || [];
      const outputMods = arch.output_modalities || [];

      let modelType = 'Image Generation';
      if (inputMods.length > 0 && outputMods.length > 0) {
        modelType = `${inputMods.join(' + ')} → ${outputMods.join(' + ')}`;
      } else if (outputMods.length === 1 && outputMods[0] === 'image') {
        modelType = 'Text → Image';
      }

      const params = model.supported_parameters || {};
      const paramLabels = [];

      if (params.aspect_ratio) {
        const arValues = params.aspect_ratio.values || [];
        const display = arValues.slice(0, 4).join(', ') + (arValues.length > 4 ? ` (+${arValues.length - 4})` : '');
        paramLabels.push(display);
      }

      if (params.resolution) {
        const resValues = params.resolution.values || [];
        if (resValues.length > 0) paramLabels.push(`Res: ${resValues.join(', ')}`);
      }

      if (params.n) {
        const maxN = params.n.max || 1;
        paramLabels.push(maxN > 1 ? `Multi: up to ${maxN} images` : 'Single image');
      }

      if (params.seed) paramLabels.push('Fixed seed');

      if (params.quality) {
        const qVals = params.quality.values || [];
        if (qVals.length > 0) paramLabels.push(`Quality: ${qVals.join(', ')}`);
      }

      if (params.background) {
        const bVals = params.background.values || [];
        if (bVals.length > 0) paramLabels.push(`Bkg: ${bVals.join(', ')}`);
      }

      if (params.output_format) {
        const ofVals = params.output_format.values || [];
        if (ofVals.length > 0) paramLabels.push(`Format: ${ofVals.join(', ')}`);
      }

      if (params.input_references) paramLabels.push('Reference images');

      const tags = [];
      if (model.top_provider?.is_preference) tags.push('Recommended');
      if (model.tags?.length) tags.push(...model.tags);
      if (!tags.length && model.description && model.description.length < 50) {
        tags.push(model.description);
      }

      const description = model.description || '';
      const truncatedDesc = description.length > 150 ? description.slice(0, 150) + '...' : description;

      // CRITICAL: Include the model ID/slug so AI can pass it to get_model_endpoints
      const modelId = model.id || '';
      const idTag = modelId ? `\n[id: ${modelId}]` : '';

      return {
        type: 'content',
        title: model.name,
        subtitle: modelType,
        content: truncatedDesc + idTag,
        tags: tags,
        labels: [
          { label: 'Capabilities', color: 'blue', value: paramLabels.length > 0 ? paramLabels.slice(0, 3).join(' · ') : 'Basic' }
        ],
        links: [
          { label: 'Details', url: `https://openrouter.ai/${model.slug || modelId.replace('/', '-')}` }
        ]
      };
    })
  };
}

async function get_model_endpoints(params, userSettings, authorizedResources){
  const modelId = params.modelId;

  if (!modelId) throw new Error('Please specify a Model ID.');

  const res = await fetch(`https://openrouter.ai/api/v1/images/models/${modelId}/endpoints`, {
    headers: {
      'HTTP-Referer': window.location.origin || 'https://typingmind.com',
      'X-Title': 'TypingMind Plugin'
    }
  });

  if (!res.ok) throw new Error(`Could not find endpoints for ${modelId}.`);
  const data = await res.json();

  return {
    cards: data.data.map(ep => ({
      type: 'list_item',
      title: ep.type,
      content: ep.url, 
      tags: [ep.status === 'available' ? 'Online' : 'Offline'],
      labels: [
        { label: 'Region', color: 'gray', value: ep.region || 'Global' }
      ]
    }))
  };
}
